// 通用 split 函数
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
int main() {
    string s;
    int num;
    getline(cin, s);
    cin >> num;
    vector<string> ans = split(s, ",");
    // 记录当前数字上次出现的位置
    map<string, int> lastPositionMp;
    int res = -1;
    int n = ans.size();
    for (int i = 0; i < n; i++) {
        string tmp = ans[i];

        if (lastPositionMp.find(tmp) != lastPositionMp.end()) {
            int lastIndex = lastPositionMp[tmp];
            if (i - lastIndex <= num) {
                res = lastIndex;
                break;
            }
​
        }
        lastPositionMp[tmp] = i;
    }
    cout << res;
    return 0;
}

