package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// split 函数，按指定分隔符分割字符串
func split(str, delimiter string) []string {
    return strings.Split(str, delimiter)
}
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line) // 移除首尾空格和换行符
​
    numStr, _ := reader.ReadString('\n')
    num, _ := strconv.Atoi(strings.TrimSpace(numStr)) // 读取整数
​
    // 按逗号分割输入
    ans := split(line, ",")
​
​
    // 记录当前数字上次出现的位置
    lastPositionMap := make(map[string]int)
    res := -1
​
    for i, tmp := range ans {
        if lastIndex, exists := lastPositionMap[tmp]; exists {
            if i-lastIndex <= num {
                res = lastIndex
                break
            }
        }
        lastPositionMap[tmp] = i
    }
​
    fmt.Println(res)
}
